-- Generated by scripts/redshift-checkpoint6.py; edit numbered sources.
-- Execute ONCE as deployment owner in database analytics.
-- Re-runs: do not recreate existing MV or role; no implicit DROP.

-- SOURCE: 01_schemas.sql
-- Execute as deployment owner, database analytics, region us-east-1.
-- No CREATE EXTERNAL DATABASE: Glue already exists and remains Terraform-owned.
SET timezone TO 'UTC';
CREATE SCHEMA IF NOT EXISTS streaming;
CREATE SCHEMA IF NOT EXISTS analytics;
CREATE EXTERNAL SCHEMA IF NOT EXISTS kinesis_source
FROM KINESIS IAM_ROLE default REGION 'us-east-1';
CREATE EXTERNAL SCHEMA IF NOT EXISTS lakehouse
FROM DATA CATALOG DATABASE 'lakehouse_db'
IAM_ROLE default REGION 'us-east-1';


-- SOURCE: 02_streaming.sql
-- Exactly one base MV consumes the existing stream. Refresh is explicitly manual.
-- Keep invalid JSON bytes for diagnostics; CASE guards JSON_PARSE.
-- Business conversions are downstream, so a bad amount cannot block ingestion.
CREATE MATERIALIZED VIEW streaming.transactions_raw
AUTO REFRESH NO AS
SELECT approximate_arrival_timestamp, refresh_time, partition_key,
       shard_id, sequence_number, kinesis_data,
       CAN_JSON_PARSE(kinesis_data) AS valid_json,
       CASE WHEN CAN_JSON_PARSE(kinesis_data)
            THEN JSON_PARSE(kinesis_data) ELSE NULL END AS payload
FROM kinesis_source."dev-transactions-stream";


-- SOURCE: 03_analytics.sql
-- SUPER paths correspond to real transaction JSON, not Java POJO field names.
-- Empty strings are normalized before TRY_CAST. Objects/arrays become NULL.
CREATE OR REPLACE VIEW analytics.transactions_typed AS
WITH fields AS (
  SELECT approximate_arrival_timestamp, refresh_time, shard_id, sequence_number,
         valid_json,
         NULLIF(TRIM(payload.transaction_id::varchar), '') AS transaction_id,
         NULLIF(TRIM(payload.payment_method::varchar), '') AS payment_method,
         LOWER(NULLIF(TRIM(payload.status::varchar), '')) AS status,
         NULLIF(TRIM(payload.amount::varchar), '') AS amount_text,
         NULLIF(TRIM(payload."timestamp"::varchar), '') AS timestamp_text
  FROM streaming.transactions_raw
), converted AS (
  SELECT *, TRY_CAST(amount_text AS decimal(20,4)) AS precise_amount,
         CASE WHEN timestamp_text ~ '^[0-9]{13}$'
              THEN DATEADD(millisecond, MOD(TRY_CAST(timestamp_text AS bigint),86400000)::integer,
                   DATEADD(day, (TRY_CAST(timestamp_text AS bigint)/86400000)::integer,
                           TIMESTAMP '1970-01-01 00:00:00'))
              ELSE TRY_CAST(timestamp_text AS timestamptz) AT TIME ZONE 'UTC'
         END AS event_time
  FROM fields
)
SELECT approximate_arrival_timestamp, refresh_time, shard_id, sequence_number,
       transaction_id, payment_method, status, event_time,
       TRY_CAST(precise_amount AS decimal(18,2)) AS amount,
       CASE WHEN NOT valid_json THEN 'invalid_json'
            WHEN transaction_id IS NULL OR payment_method IS NULL OR status IS NULL
              THEN 'missing_required_field'
            WHEN amount_text !~ '^[0-9]+([.][0-9]{1,2})?$'
              OR precise_amount IS NULL OR precise_amount < 0
              OR precise_amount <> ROUND(precise_amount,2)
              OR TRY_CAST(precise_amount AS decimal(18,2)) IS NULL THEN 'invalid_amount'
            WHEN event_time IS NULL THEN 'invalid_timestamp'
            ELSE NULL END AS validation_error
FROM converted;

-- Ordinary aggregate view avoids assumptions about incremental eligibility of
-- SUPER extraction/timestamp conversions in a nested MV. Always reads base state.
CREATE OR REPLACE VIEW analytics.transactions_per_minute AS
SELECT DATE_TRUNC('minute',event_time) AS window_start, payment_method,
       COUNT(*) AS transaction_count,
       SUM(amount) AS total_amount,
       AVG(amount)::decimal(38,6) AS average_amount,
       SUM(CASE WHEN status='approved' THEN 1 ELSE 0 END) AS approved_count,
       SUM(CASE WHEN status='rejected' THEN 1 ELSE 0 END) AS rejected_count,
       SUM(CASE WHEN status='approved' THEN amount ELSE 0 END) AS approved_amount
FROM analytics.transactions_typed
WHERE validation_error IS NULL
GROUP BY 1,2;


-- SOURCE: 04_iceberg.sql
-- Iceberg contains approved aggregates, NOT individual transactions.
-- Both sides are collapsed to exactly one row per UTC minute/payment method.
-- Historical duplicates are summed, not hidden: drift should expose replay.
-- Late data and Flink watermark/checkpoint timing can temporarily cause drift.
CREATE OR REPLACE VIEW analytics.recent_vs_iceberg AS
WITH recent AS (
  SELECT DATE_TRUNC('minute',event_time) AS window_start, payment_method,
         COUNT(*) AS approved_count, SUM(amount) AS approved_amount
  FROM analytics.transactions_typed
  WHERE validation_error IS NULL AND status='approved'
  GROUP BY 1,2
), historical AS (
  SELECT window_start, payment_method,
         SUM(transaction_count) AS approved_count, SUM(total_amount) AS approved_amount
  FROM lakehouse.transaction_aggregates
  GROUP BY 1,2
)
SELECT r.window_start, r.payment_method,
       r.approved_count AS recent_approved_count,
       h.approved_count AS iceberg_approved_count,
       r.approved_amount AS recent_approved_amount,
       h.approved_amount AS iceberg_approved_amount,
       r.approved_count-h.approved_count AS count_difference,
       r.approved_amount-h.approved_amount AS amount_difference
FROM recent r JOIN historical h
ON r.window_start=h.window_start AND r.payment_method=h.payment_method
WITH NO SCHEMA BINDING;


-- SOURCE: 05_security.sql
-- Run once as owner. AWS IAM role grants service access; this DB role grants SQL.
CREATE ROLE checkpoint6_analyst;
REVOKE ALL ON SCHEMA streaming FROM PUBLIC;
REVOKE ALL ON SCHEMA analytics FROM PUBLIC;
REVOKE ALL ON SCHEMA kinesis_source FROM PUBLIC;
REVOKE ALL ON SCHEMA lakehouse FROM PUBLIC;
GRANT USAGE ON SCHEMA analytics TO ROLE checkpoint6_analyst;
-- Late-binding view resolution also needs USAGE on its external schema.
-- The IAM execution role limits external reads to the single Iceberg table.
GRANT USAGE ON SCHEMA lakehouse TO ROLE checkpoint6_analyst;
GRANT SELECT ON analytics.transactions_typed TO ROLE checkpoint6_analyst;
GRANT SELECT ON analytics.transactions_per_minute TO ROLE checkpoint6_analyst;
GRANT SELECT ON analytics.recent_vs_iceberg TO ROLE checkpoint6_analyst;
-- Analyst cannot refresh MVs, create schemas, read raw bytes, or assume IAM role.
-- Explicitly bind a real authenticated DB identity after approving membership:
-- GRANT ROLE checkpoint6_analyst TO "IAM:analyst-name";


-- SOURCE: 06_validation.sql
-- Manual sequence: publish test records, refresh once, query; no one-second loop.
REFRESH MATERIALIZED VIEW streaming.transactions_raw;
SELECT transaction_id,event_time,amount,payment_method,status,validation_error
FROM analytics.transactions_typed ORDER BY approximate_arrival_timestamp DESC LIMIT 20;
SELECT * FROM analytics.transactions_per_minute ORDER BY window_start DESC LIMIT 20;
SELECT * FROM lakehouse.transaction_aggregates
WHERE window_start >= TIMESTAMP '2026-11-04 00:00:00'
  AND window_start < TIMESTAMP '2026-11-05 00:00:00';
-- A comparison, not a UNION of overlapping histories; do not add the two totals.
SELECT * FROM analytics.recent_vs_iceberg ORDER BY window_start DESC LIMIT 20;
SELECT * FROM svv_role_grants WHERE role_name='checkpoint6_analyst';
SELECT * FROM svv_relation_privileges WHERE identity_name='checkpoint6_analyst';


-- SOURCE: 07_monitoring.sql
-- Serverless-compatible SYS views. Owner sees their own refreshes; superuser all.
SELECT * FROM sys_stream_scan_states
WHERE external_schema_name='kinesis_source' ORDER BY record_time DESC LIMIT 20;
SELECT * FROM sys_stream_scan_errors
WHERE external_schema_name='kinesis_source' ORDER BY record_time DESC LIMIT 20;
SELECT mv_name,refresh_type,status,start_time,end_time,duration
FROM sys_mv_refresh_history
WHERE schema_name='streaming' ORDER BY start_time DESC LIMIT 20;
SELECT * FROM sys_mv_state ORDER BY start_time DESC LIMIT 20;
SELECT COUNT(*) AS stored_records, MAX(approximate_arrival_timestamp) AS last_arrival,
       MAX(refresh_time) AS last_ingest_refresh
FROM streaming.transactions_raw;
SELECT validation_error,COUNT(*) AS records
FROM analytics.transactions_typed GROUP BY 1;
-- refresh_time is refresh start, not record visibility time. Negative values are
-- possible for records arriving during a refresh. Data API observation separately
-- measures upper-bound end-to-end latency; never present this as an SLA.
SELECT shard_id,sequence_number,approximate_arrival_timestamp,refresh_time,
       DATEDIFF(millisecond,approximate_arrival_timestamp,GETDATE()) AS arrival_age_ms
FROM streaming.transactions_raw ORDER BY approximate_arrival_timestamp DESC LIMIT 20;
